        c = new MONEY_BOX();
    }

    function _run(address _log1, address _log2) internal {
        try c.SetLogFile(_log1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetLogFile(_log2) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(address _log1, address _log2) public {
